<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Http\Resources\VehicleResource;use App\Models\Vehicle;use App\Services\ActivityLogService;use Illuminate\Http\Request;use Illuminate\Support\Str;
class VehicleController extends Controller {
 public function index(Request $r){$q=Vehicle::with(['brand','category','location','images','features'])->when($r->search,fn($x,$v)=>$x->where('name','like',"%$v%"))->when($r->status,fn($x,$v)=>$x->where('status',$v))->latest();return VehicleResource::collection($q->paginate(50));}
 public function store(Request $r){$d=$this->validateData($r);$d['slug']=$d['slug']??Str::slug($d['name']).'-'.Str::lower(Str::random(5));$v=Vehicle::create($d);ActivityLogService::record('Created',$v,null,$v->toArray(),$r,'Created vehicle');return new VehicleResource($v->load(['brand','category','location','images','features']));}
 public function show(Vehicle $vehicle){return new VehicleResource($vehicle->load(['brand','category','location','images','features']));}
 public function update(Request $r,Vehicle $vehicle){$old=$vehicle->toArray();$d=$this->validateData($r,$vehicle->id);if(isset($d['name'])&&!isset($d['slug']))$d['slug']=$vehicle->slug?:Str::slug($d['name']);$vehicle->update($d);ActivityLogService::record('Updated',$vehicle,$old,$vehicle->fresh()->toArray(),$r,'Updated vehicle');return new VehicleResource($vehicle->fresh()->load(['brand','category','location','images','features']));}
 public function destroy(Request $r,Vehicle $vehicle){$old=$vehicle->toArray();abort_if($vehicle->bookings()->whereIn('status',['Pending','Confirmed','In Progress'])->exists(),422,'Vehicle has active bookings and cannot be deleted.');$vehicle->delete();ActivityLogService::record('Deleted',$vehicle,$old,null,$r,'Deleted vehicle');return response()->json(['message'=>'Vehicle deleted.']);}
 private function validateData(Request $r,?int $id=null):array{return $r->validate(['name'=>'required|string|max:190','slug'=>'nullable|string|max:190|unique:vehicles,slug'.($id?",$id":''),'brand_id'=>'nullable|exists:vehicle_brands,id','model'=>'nullable|string|max:120','year'=>'nullable|integer|min:1990|max:'.(now()->year+2),'category_id'=>'nullable|exists:vehicle_categories,id','transmission'=>'nullable|string|max:80','fuel_type'=>'nullable|string|max:80','seats'=>'nullable|integer|min:1|max:30','doors'=>'nullable|integer|min:1|max:10','mileage_policy'=>'nullable|string|max:190','daily_price'=>'required|numeric|min:0','weekly_price'=>'nullable|numeric|min:0','monthly_price'=>'nullable|numeric|min:0','weekend_price'=>'nullable|numeric|min:0','holiday_price'=>'nullable|numeric|min:0','deposit'=>'nullable|numeric|min:0','driver_fee'=>'nullable|numeric|min:0','extra_km_fee'=>'nullable|numeric|min:0','late_return_fee'=>'nullable|numeric|min:0','driver_available'=>'nullable|boolean','self_drive_available'=>'nullable|boolean','location_id'=>'nullable|exists:locations,id','short_description'=>'nullable|string|max:1000','description'=>'nullable|string','main_image'=>'nullable|string|max:500','status'=>'nullable|in:active,inactive,maintenance','operational_status'=>'nullable|in:Available,Reserved,On Rent,Returned - Inspection Pending,Under Maintenance,Blocked,Retired','odometer'=>'nullable|integer|min:0','registration_expires_at'=>'nullable|date','insurance_expires_at'=>'nullable|date','featured'=>'nullable|boolean','sort_order'=>'nullable|integer|min:0']);}
}
